// @svelters/native-runtime: the runtime that components generated by the svelters compiler target
// (docs/notes/native-compiler/runtime-contract.md). Reactivity comes from the core (./core: the
// compiler-facing contract and the internals below, backed by Svelte's signals, effects and
// batching through one adapter, ./core/svelte.js); this module only turns component code into host
// ops (plans/architecture/backend-abi.md "JS-side host ops"). There is no JS tree of DOM-like nodes
// and no anchors: containers and regions keep just the ordering native insertion needs.
// Plain ES2022, no globals besides __svelters_host / __svelters_dispatch / __svelters_dispatch_sync /
// __svelters_gone / __svelters_node.
import { DEV } from 'esm-env';
import * as $ from './core/index.js';
import {
  active,
  block,
  boundary_handler,
  boundary_scope,
  branch,
  clsx,
  current_boundary,
  destroy,
  destroyed as effectDestroyed,
  pause,
  resume,
  set_intro,
  transition as svelteTransition,
  animation as svelteAnimation,
  EFFECT_TRANSPARENT,
  flush,
  flushing_sync,
  init_dev,
  queue_task,
  mutable_state,
  trace_item,
  capture_context,
  release_context,
  reorder,
  root as componentRoot,
  root_boundary,
} from './core/internal.js';
// The X6 styling (classes, widget name, inline style, sheets, tokens) works on any node with `h`,
// `tag`, `attrs` and `sc`: compiled components drive it through `attr`.
import { bindElements, bindSetterHooks, forgetStyle, markStyleDirty } from './style.js';
// TR1: transitions (the runtime node's Element facade, the animation player, the visual channels)
import { RUNTIME_EVENTS, defineFacade } from './motion.js';
import { ROW_OUTLETS, TOPLEVELS } from './bindings.generated.js';
import { parseSetterValue, propOf } from '@svelters/style/runtime';
// ABI v2.6 property observation (REACTIVITY.md section 7): installs `__svelters_changed` and the
// `@svelters/types` tracker when the runtime loads.
export { observeProp, trackProp, trackLocal, invalidateProp } from './observe.js';
// R2: `bind:` lowered onto observation (./bind-observe.js, over the tracker API of ./observe.js).
export { bind_once, bind_prop, bind_readonly } from './bind-observe.js';

/** `set(node, prop, RESTORE)` writes the value `capture(node, prop)` read. */
export const RESTORE = Symbol('svelters.RESTORE');

const host = () => globalThis.__svelters_host;

// handle -> Native, per host object (tests run several TestHosts in one process).
const tables = new WeakMap();
function table(hs = host()) {
  let t = tables.get(hs);
  if (!t) tables.set(hs, (t = new Map()));
  return t;
}

/** The ownership scope new natives and handlers belong to (root, branch or each item). */
let scope = null;

class Scope {
  constructor(parent) {
    this.parent = parent;
    this.natives = []; // creation order
    this.children = new Set();
    this.handlers = []; // [node, signal, fn, flags]
    parent?.children.add(this);
  }
}

class Native {
  constructor(kind, h, top) {
    this.kind = kind;
    this.h = h;
    this.host = host();
    this.top = top ?? null; // toplevel kinds: { present, show }; `shown` once its show policy ran
    this.shown = false;
    this.nested = false; // a toplevel declared inside an element (transient for the enclosing one)
    this.attached = false; // attached to its parent element (an event controller, a context menu)
    this.scope = scope;
    this.owner = null; // the container or region this node was appended to
    this.np = null; // native parent (Native) while inserted
    this.slotName = null;
    this.dead = null; // reason from __svelters_gone
    this.destroyed = false;
    this.last = new Map(); // prop -> last value written (or reported by the native side)
    this.captured = new Map();
    this.tokens = new Map(); // prop -> Set of tokens
    this.handlers = new Map(); // `${signal}\0${flags}` -> [fn]
    this.listening = new Set(); // same keys, while the host listens
    this.cattrs = new Map(); // `parent:` child attributes, by name (sent after every insert)
    this.passive = new Map(); // signal -> [fn]: `track` mirrors, run before the handlers, never listened
    this.slots = new Map(); // slot name (null = default) -> Slot
    this.attrs = {}; // class / id / style for the X6 styling (`attr`)
    this.sc = null; // what styling has been sent (./style.js)
  }

  /** Whether the native object exists (not destroyed by us, not dead natively). */
  alive() {
    return !this.dead && !this.destroyed;
  }

  /** The element tag (the X6 styling's kind table is keyed by tag). */
  get tag() {
    return this.kind;
  }

  // Native access for `bind:this` (types/native.d.ts `NativeElement`).

  /** Native handle while alive, else null. */
  get handle() {
    return alive(this) ? this.h : null;
  }

  /** What the host converts a node argument to; null when dead. */
  get svlHandle() {
    return this.handle;
  }

  /** Calls a native method; throws StaleHandleError (with the death reason) when dead. */
  call(method, ...args) {
    return this.host.call(liveHandle(this), method, args);
  }

  /**
   * Writes a native property directly (`bind:this`, borrowed nodes); throws StaleHandleError when
   * dead. Not tracked like `set`: the compiler's own writes go through `$n.set`.
   */
  setProp(name, value) {
    this.host.setProp(liveHandle(this), name, value);
  }

  /** Reads a native property; throws StaleHandleError when dead. */
  getProp(name) {
    return this.host.getProp(liveHandle(this), name);
  }
}

/**
 * Thrown by a node's native-access methods when it has no live native object. `reason` is
 * 'destroyed' once the runtime destroyed it, or the native death reason (ABI v2 `gone`).
 */
export class StaleHandleError extends Error {
  constructor(kind, reason) {
    super(`<${kind}> is dead: ${reason}`);
    this.name = 'StaleHandleError';
    this.reason = reason;
  }
}

function liveHandle(n) {
  if (n.dead) throw new StaleHandleError(n.kind, n.dead);
  if (n.destroyed) throw new StaleHandleError(n.kind, 'destroyed');
  return n.h;
}

const alive = (n) => !n.dead && !n.destroyed;

/** A native node's slot: the place its children go. */
class Slot {
  constructor(node, name) {
    this.node = node;
    this.name = name;
    this.items = [];
  }
}

/** The mount target: toplevels appended here are presented, not inserted. */
class Root {
  constructor() {
    this.items = [];
  }
}

/** A run of items inside a container: if/each blocks, their branches, component calls. */
class Region {
  constructor(owner) {
    this.owner = owner;
    this.items = [];
    this.scope = null; // set for branches
    this.effect = null;
  }
}

function newRegion(container) {
  const r = new Region(container);
  container.items.push(r);
  return r;
}

/** The slot or root a container (or region) ultimately places its natives in. */
function target(c) {
  while (c instanceof Region) c = c.owner;
  return c;
}

/** Inserted, live natives of `item` in order (descending into regions). */
function natives(item, out = []) {
  if (item instanceof Native) {
    if (item.np && alive(item)) out.push(item);
  } else for (const x of item.items) natives(x, out);
  return out;
}

/** Not positioned among its parent's children: a transient toplevel or an attached node. */
const unplaced = (n) => n.nested || n.attached;

function firstNative(item) {
  if (item instanceof Native) return item.np && alive(item) && !unplaced(item) ? item : null;
  // TR1: an outroing branch keeps its natives where they are, but is never an insertion anchor:
  // live natives keep their relative order, new ones land after the outroing ones (as in Svelte)
  if (item.outro) return null;
  for (const x of item.items) {
    const n = firstNative(x);
    if (n) return n;
  }
  return null;
}

/** The inserted native that follows `item` in its native parent+slot, or null (= end). */
function nextNative(item) {
  for (let it = item; ; it = it.owner) {
    const list = it.owner.items;
    for (let i = list.indexOf(it) + 1; i < list.length; i++) {
      const n = firstNative(list[i]);
      if (n) return n;
    }
    if (!(it.owner instanceof Region)) return null;
  }
}

function attach(node) {
  const t = target(node.owner);
  if (t instanceof Root) {
    if (!node.top) throw new Error(`only toplevel kinds may be mounted at the root, got <${node.kind}>`);
    if (alive(node)) showTop(node);
    settle();
    return;
  }
  if (node.top) {
    // X7: transient for the enclosing toplevel, shown after it (settle)
    node.nested = true;
    pendingTops.push(node);
    settle();
    return;
  }
  const parent = t.node;
  if (!alive(parent) || !alive(node)) return;
  if (node.attached) {
    // an event controller or context menu: inserted into the element itself, no slot or position
    node.host.insert(parent.h, node.h, null, undefined);
    node.np = parent;
    return;
  }
  const before = nextNative(node);
  node.host.insert(parent.h, node.h, before ? before.h : null, t.name ?? undefined);
  node.np = parent;
  node.slotName = t.name;
  applyChildAttrs(node);
  if (pendingTops.length) settle();
}

// ---------------------------------------------------------------------------------------------
// Toplevels (X7, backend-abi.md "Toplevels in the tree")

/** Toplevels declared inside an element, waiting for the enclosing toplevel to be known or shown. */
let pendingTops = [];

/**
 * The toplevel `node` is declared in: the nearest enclosing native of a toplevel kind; null when
 * there is none (mounted into a target); undefined while the chain of appends is not complete.
 */
function enclosingTop(node) {
  for (let c = node.owner; ; ) {
    const t = target(c);
    if (t instanceof Root) return null;
    const n = t.node;
    if (n.top) return n;
    if (n.mountTarget) return null;
    if (!n.owner) return undefined;
    c = n.owner;
  }
}

/** Inserts pending toplevels into their enclosing toplevel (transient) and shows them after it. */
function settle() {
  for (let progress = true; progress && pendingTops.length; ) {
    progress = false;
    for (const n of [...pendingTops]) {
      const anc = enclosingTop(n);
      const drop = !alive(n) || (anc && !alive(anc));
      if (!drop && anc === undefined) continue;
      if (!drop && anc && !n.np) {
        n.host.insert(anc.h, n.h, null, undefined);
        n.np = anc;
        progress = true;
      }
      if (drop || !anc || anc.shown) {
        pendingTops.splice(pendingTops.indexOf(n), 1);
        if (!drop) showTop(n);
        progress = true;
      }
    }
  }
}

/** The first of `names` the host resolves as a method of `node`'s kind (the first without ids). */
function pickMethod(node, names) {
  const hs = node.host;
  if (names.length === 1 || typeof hs.methodId !== 'function' || typeof hs.kindId !== 'function') return names[0];
  let kid;
  try {
    kid = hs.kindId(node.kind);
  } catch {
    return names[0];
  }
  for (const n of names) {
    try {
      if (hs.methodId(kid, n) != null) return n;
    } catch {
      // not a method of this kind
    }
  }
  return names[names.length - 1];
}

/**
 * The `show` policy: `modal` (dialog default: the modal method, `modal` set first when the kind
 * has it and the app did not set it), `modeless` (window default: the spec's present method) or
 * `none` (the app opens it through `bind:this`).
 */
function showTop(node) {
  node.shown = true;
  const spec = Object.hasOwn(TOPLEVELS, node.kind) ? TOPLEVELS[node.kind] : null;
  const mode = node.top.show ?? (spec?.dialog ? 'modal' : 'modeless');
  if (mode === 'none') return;
  let m;
  if (mode === 'modal' && spec) {
    m = pickMethod(node, spec.open);
    if (m === 'present' && spec.modalProp && !node.last.has('modal')) set(node, 'modal', true);
  } else m = node.top.present ?? pickMethod(node, spec?.modeless ?? ['present']);
  node.host.call(node.h, m, []);
}

// Sends every `parent:` attribute of `node` to its native parent; called right after an insert
// (first placement and every re-insert of a keyed move).
function applyChildAttrs(node) {
  if (node.cattrs.size === 0 || !node.np || !alive(node) || !alive(node.np)) return;
  for (const [name, value] of node.cattrs) node.host.setChildAttr(node.np.h, node.h, name, value);
}

/**
 * `parent:<name>={value}`: a per-child attribute owned by the native parent (a grid cell, a tab
 * label). Stored on the node and sent with `host.setChildAttr(parent, child, name, value)` once
 * the node is inserted, on every change, and after every re-insert. `null`/`undefined` resets it
 * (sent as `null`) and drops it from the set.
 */
export function child_attr(node, name, value) {
  if (value === undefined) value = null;
  if (node.cattrs.has(name) && node.cattrs.get(name) === value) return;
  if (value === null) node.cattrs.delete(name);
  else node.cattrs.set(name, value);
  if (node.np && alive(node) && alive(node.np)) node.host.setChildAttr(node.np.h, node.h, name, value);
}

function detach(node) {
  if (node.np && alive(node) && alive(node.np)) node.host.remove(node.np.h, node.h);
  node.np = null;
}

// ---------------------------------------------------------------------------------------------
// Nodes and props

let outletKind;
/** The tag of a virtualized list's row outlet on this host: the first ROW_OUTLETS candidate it resolves. */
export function rowOutlet() {
  if (outletKind === undefined) {
    const hs = host();
    const ok = (t) => {
      try {
        return typeof hs.kindId === 'function' && typeof hs.kindId(t) === 'number';
      } catch {
        return false;
      }
    };
    outletKind = ROW_OUTLETS.find(ok) ?? ROW_OUTLETS[0];
  }
  return outletKind;
}

export function element(kind, present) {
  if (present) return toplevel(kind, present);
  return create(kind, null);
}

function create(kind, top) {
  if (!scope) throw new Error('element() outside a mounted component');
  const hs = host();
  const n = new Native(kind, hs.create(kind), top);
  table(hs).set(n.h, n);
  scope.natives.push(n);
  return n;
}

/**
 * A toplevel kind (X7). At the root it is shown by its `show` policy once its subtree is complete;
 * inside an element it becomes transient for the enclosing toplevel (`host.insert(enclosing, h)`)
 * and is shown after that one. `present`: the spec's modeless show method (null: picked from
 * TOPLEVELS); `show`: a static `show="modal|modeless|none"`.
 */
export function toplevel(kind, present = null, show = undefined) {
  return create(kind, { present, show });
}

/** A kind that attaches to its parent element (spec `attaches_to`): inserted with no slot or position. */
export function attached(kind) {
  const n = create(kind, null);
  n.attached = true;
  return n;
}

export function set(node, prop, value) {
  if (value === RESTORE) {
    if (!node.captured.has(prop)) throw new Error(`set ${prop}: RESTORE without capture()`);
    value = node.captured.get(prop);
  }
  if (!alive(node)) return;
  if (node.last.has(prop) && Object.is(node.last.get(prop), value)) return;
  node.last.set(prop, value);
  node.host.setProp(node.h, prop, value);
}

/**
 * Records `value` as the native value of `prop` without writing it: the spec's native default of a
 * freshly created widget. A later `set` of the same value is then a no-op.
 */
export function assume(node, prop, value) {
  if (!node.last.has(prop)) node.last.set(prop, value);
}

// ---------------------------------------------------------------------------------------------
// Styling (X6 sheets and the inline style; setter rules are matched at compile time)

bindElements(() => table().values());
// inline setter properties of a dynamic `style={...}` (static ones are compiled). Precedence:
// explicit attributes (`$n.explicit`, from the compiler) > this inline style > the rules (matched at
// compile time, written through `rule_set` / `rule_attr` on such elements) > the native value.
bindSetterHooks({
  hasProp: (n, prop, native) => !!n.explicit && (n.explicit.props.has(prop) || n.explicit.props.has(native)),
  hasChildAttr: (n, name) => !!n.explicit && n.explicit.attrs.has(name),
  readProp: (n, prop) => n.host.getProp(n.h, prop),
  writeProp: (n, prop, value) => {
    (n.inlineProps ??= new Set()).add(prop);
    set(n, prop, value);
  },
  // no inline declaration sets `prop` any more: back to the rules' value, else the native one
  restoreProp: (n, prop, orig) => {
    n.inlineProps?.delete(prop);
    set(n, prop, n.ruled?.has(prop) ? n.ruled.get(prop) : orig);
  },
  writeChildAttr: (n, name, value) => {
    if (value === null) {
      n.inlineAttrs?.delete(name);
      value = n.ruledAttrs?.get(name) ?? null;
    } else (n.inlineAttrs ??= new Set()).add(name);
    child_attr(n, name, value);
  },
});

/** The explicit props and `parent:` attributes of an element with a dynamic `style={...}`. */
export function explicit(node, props, attrs) {
  node.explicit = { props: new Set(props), attrs: new Set(attrs) };
}

/** A rule's value for `prop` on an element with a dynamic `style={...}`: its inline setters win. */
export function rule_set(node, prop, value) {
  (node.ruled ??= new Map()).set(prop, value);
  if (!node.inlineProps?.has(prop)) set(node, prop, value);
}

/** A rule's child attribute on an element with a dynamic `style={...}` (see rule_set). */
export function rule_attr(node, name, value) {
  (node.ruledAttrs ??= new Map()).set(name, value ?? null);
  if (!node.inlineAttrs?.has(name)) child_attr(node, name, value);
}

/**
 * `class`, `id` or `style` of a native element for the X6 styling (as the retired renderer's
 * attributes): sent with `host.style` at the end of the job, diffed.
 */
export function attr(node, name, value) {
  if (value === undefined || value === null || value === false) {
    if (!(name in node.attrs)) return;
    delete node.attrs[name];
  } else {
    if (node.attrs[name] === value) return;
    node.attrs[name] = value;
  }
  if (alive(node)) markStyleDirty(node);
}

/** The class string: `base`, the dynamic class set `dyn` (or null), then `[name, on]` toggles. */
export function class_name(base, dyn, toggles) {
  const out = base ? base.split(' ') : [];
  if (dyn) for (const c of dyn) if (!out.includes(c)) out.push(c);
  for (const [c, on] of toggles) {
    const i = out.indexOf(c);
    if (on && i < 0) out.push(c);
    else if (!on && i >= 0) out.splice(i, 1);
  }
  return out.join(' ');
}

/** The inline style text: `base` plus `[property, value]` pairs (nullish values dropped), as Svelte's `style:`. */
export function style_text(base, directives) {
  let out = base == null ? '' : String(base).trim();
  for (const [k, v] of directives) {
    if (v == null || v === '') continue;
    out += `${out && !out.endsWith(';') ? '; ' : ''}${k}: ${v}`;
  }
  return out;
}

/**
 * The native value of a `style:<setter>={value}`: numbers, booleans and objects pass through,
 * strings are parsed like `style=` (`'8px'`, `'center'`). A bad value warns and writes null.
 */
export function setter_value(toolkit, name, value) {
  if (typeof value !== 'string') return value ?? null;
  const r = parseSetterValue(toolkit, name, propOf(toolkit, name), value);
  if (r.error) {
    console.warn(`[svelters/style] ${r.error}`);
    return null;
  }
  return r.value;
}

export function capture(node, prop) {
  if (node.captured.has(prop) || !alive(node)) return;
  const v = node.host.getProp(node.h, prop);
  node.captured.set(prop, v);
  if (!node.last.has(prop)) node.last.set(prop, v);
}

export function token(node, prop, tok, on) {
  if (!alive(node)) return;
  let t = node.tokens.get(prop);
  if (!t) {
    if (!node.last.has(prop)) node.last.set(prop, node.host.getProp(node.h, prop));
    const init = node.last.get(prop);
    // ABI v3: a token list prop (GTK GStrv) travels as a list of strings
    t = new Set(Array.isArray(init) ? init : String(init ?? '').split(/\s+/).filter(Boolean));
    node.tokens.set(prop, t);
  }
  if (t.has(tok) === !!on) return;
  if (on) t.add(tok);
  else t.delete(tok);
  set(node, prop, [...t]);
}

// ---------------------------------------------------------------------------------------------
// Signals

/** `listen_ex` flags (ABI v2.2). */
export const LISTEN_AFTER = 1;
export const LISTEN_CAPTURE = 2;

const hkey = (signal, flags) => `${signal}\0${flags}`;

// `listen` for flags 0, `listen_ex` (a 4th argument) otherwise.
function hostListen(node, signal, on, flags) {
  // TR1: `introstart` etc. are dispatched by the runtime itself (the node's `dispatchEvent`)
  if (flags === 0 && RUNTIME_EVENTS.has(signal)) return;
  if (flags) node.host.listen(node.h, signal, on, flags);
  else node.host.listen(node.h, signal, on);
}

/**
 * Registers `fn` for native `signal` with listen `flags` (LISTEN_AFTER | LISTEN_CAPTURE; 0 =
 * plain). Each (signal, flags) is its own native connection: `host.listen` on its first handler.
 */
export function on(node, signal, fn, flags = 0) {
  const k = hkey(signal, flags);
  let list = node.handlers.get(k);
  if (!list) node.handlers.set(k, (list = []));
  list.push(fn);
  scope?.handlers.push([node, signal, fn, flags]);
  if (!node.listening.has(k) && alive(node)) {
    node.listening.add(k);
    hostListen(node, signal, true, flags);
  }
}

function off(node, signal, fn, flags = 0) {
  const k = hkey(signal, flags);
  const list = node.handlers.get(k);
  const i = list ? list.indexOf(fn) : -1;
  if (i < 0) return;
  list.splice(i, 1);
  if (list.length === 0 && node.listening.has(k)) {
    node.listening.delete(k);
    if (alive(node)) hostListen(node, signal, false, flags);
  }
}

// Event names are native signal names: `listen(type)` listens to the signal `type` (no aliases).

const flagsOf = (options) => {
  if (options === true) return LISTEN_CAPTURE;
  if (!options || typeof options !== 'object') return 0;
  return (options.capture ? LISTEN_CAPTURE : 0) | (options.after ? LISTEN_AFTER : 0);
};

/**
 * The `listen(type, handler, { after, capture })` attachment components import from here
 * (`{@attach listen(...)}`).
 * The compiler lowers a statically known call to `$n.listen(signal, handler, flags)` instead.
 */
export function listen(type, handler, options = {}) {
  const signal = type;
  const flags = typeof options === 'number' ? options : flagsOf(options);
  return (node) => {
    // registered outside the attachment's scope bookkeeping: the cleanup removes it
    const prev = scope;
    scope = null;
    try {
      on(node, signal, handler, flags);
    } finally {
      scope = prev;
    }
    return () => off(node, signal, handler, flags);
  };
}

const reported = (node, prop, arg, args) => (arg >= 0 ? args[arg] : node.host.getProp(node.h, prop));

/** Two-way binding: `prop` follows `get()`, and `signal` reports native changes to `setv`. */
export function bind(node, prop, signal, arg, get, setv) {
  $.template_effect(() => set(node, prop, get()));
  on(node, signal, (...args) => {
    const v = reported(node, prop, arg, args);
    node.last.set(prop, v);
    if (!Object.is(v, $.untrack(get))) setv(v);
  });
}

/**
 * One-way prop the native side also changes (`text={x}` on an entry): records the value `signal`
 * reports so that writing it back is a no-op. Passive, like the renderer's mirror of entry
 * `changed`: it runs when the signal is delivered because another handler listens, and does not
 * make the host listen by itself.
 */
export function track(node, prop, signal, arg) {
  let list = node.passive.get(signal);
  if (!list) node.passive.set(signal, (list = []));
  list.push((...args) => void node.last.set(prop, reported(node, prop, arg, args)));
}

const handlersOf = (node, signal, flags) => [...(node.handlers.get(hkey(signal, flags)) ?? [])];

// TR1: the `Element` slice Svelte's transition code uses (src/motion.js)
defineFacade(Native.prototype, { handlers: (node, type) => handlersOf(node, type, 0) });

/** TR1: whether `node` or a native ancestor is inert (outroing): its events are dropped. */
function inertNode(node) {
  for (let n = node; n; n = n.np) if (n.inertFlag) return true;
  return false;
}

/**
 * The event object of a sync signal (`__svelters_dispatch_sync`) and of its deferred delivery:
 * NativeEvent. Svelte ignores handler return values, so the native result
 * comes from this object: `e.result = v` wins, else `e.preventDefault()` / `e.stopPropagation()`
 * give `true`, else `null` (toolkit default). Listeners get `(event, ...args)`. When `deferred`
 * the toolkit did not wait (JS was busy): the flags stay settable but are ignored.
 */
export class NativeEvent {
  constructor(type, signal, target, args, deferred) {
    this.type = type;
    this.signal = signal;
    this.target = target;
    this.args = args;
    this.deferred = deferred;
    this.cancelable = !deferred;
    this.defaultPrevented = false;
    this.cancelBubble = false;
    this.result = undefined;
    this.immediateStopped = false;
  }

  preventDefault() {
    if (this.cancelable) this.defaultPrevented = true;
  }

  stopPropagation() {
    if (this.cancelable) this.cancelBubble = true;
  }

  stopImmediatePropagation() {
    this.stopPropagation();
    this.immediateStopped = true;
  }
}


/**
 * `__svelters_dispatch(h, signal, args, deferred, flags)`: runs the handlers registered for
 * (signal, flags) in registration order. Plain signals: handlers get the args. `deferred`: a
 * sync signal delivered late; handlers get `(NativeEvent, ...args)` as from `dispatch_sync`, and
 * the result is ignored. Unknown (destroyed or dead) handles are ignored.
 */
export function dispatch(h, signal, args = [], deferred = false, flags = 0) {
  const node = table().get(h);
  if (!node || !alive(node)) return;
  if (inertNode(node)) return;
  if (deferred) {
    const ev = new NativeEvent(signal, signal, node, args, true);
    for (const fn of handlersOf(node, signal, flags)) {
      fn.call(node, ev, ...args);
      if (ev.immediateStopped) break;
    }
    return;
  }
  if (flags === 0) for (const fn of node.passive.get(signal) ?? []) fn.apply(node, args);
  for (const fn of handlersOf(node, signal, flags)) fn.apply(node, args);
}

/**
 * `__svelters_dispatch_sync(h, signal, args, flags)`: a sync native signal (`call_sync`) runs its
 * handlers now with a NativeEvent and returns the toolkit result (see NativeEvent). An exception
 * propagates (the host reports it and the toolkit uses its default); a handler returning a
 * Promise draws a warning.
 */
export function dispatch_sync(h, signal, args = [], flags = 0) {
  const node = table().get(h);
  if (!node || !alive(node)) throw new Error(`dispatchSync: unknown handle ${h}`);
  // TR1: an outroing subtree is inert: the toolkit gets its default
  if (inertNode(node)) return null;
  const ev = new NativeEvent(signal, signal, node, args, false);
  for (const fn of handlersOf(node, signal, flags)) {
    const r = fn.call(node, ev, ...args);
    if (r !== null && typeof r === 'object' && typeof r.then === 'function') {
      console.warn(`sync handler for '${signal}' returned a Promise: flags set after its first await come too late and are ignored`);
    }
    if (ev.immediateStopped) break;
  }
  if (ev.result !== undefined) return ev.result;
  return ev.defaultPrevented || ev.cancelBubble ? true : null;
}

export function gone(h, reason) {
  const t = table();
  const b = borrowedTable();
  const node = t.get(h) ?? b.get(h)?.deref();
  b.delete(h);
  if (!node) return;
  t.delete(h);
  node.dead = reason;
  node.np = null;
}

// Borrowed handles (native objects a getter or call returned: a parent, a root, an inner child),
// `nodeFor`: a handle we created resolves to its own node (identity across
// getters), any other to one stable `borrowed` node per handle, held weakly and released natively
// (`host.destroy`) once collected. A borrowed node is never part of the tree; it goes stale when
// the host reports it gone.
const borrowedTables = new WeakMap(); // host -> Map<handle, WeakRef<Native>>
function borrowedTable(hs = host()) {
  let t = borrowedTables.get(hs);
  if (!t) borrowedTables.set(hs, (t = new Map()));
  return t;
}
const borrowedRegistry =
  typeof FinalizationRegistry === 'function'
    ? new FinalizationRegistry(({ hs, h }) => {
        const t = borrowedTable(hs);
        if (t.get(h)?.deref()) return; // a newer wrapper took over the handle
        t.delete(h);
        try {
          hs.destroy(h);
        } catch {
          // the host is shutting down
        }
      })
    : null;

/** `__svelters_node(h)`: the node for a handle in a host call result. */
export function nodeFor(h) {
  const hs = host();
  const own = table(hs).get(h);
  if (own) return own;
  const b = borrowedTable(hs);
  const live = b.get(h)?.deref();
  if (live) return live;
  const prev = scope;
  scope = null;
  const n = new Native('borrowed', h, null);
  scope = prev;
  n.borrowed = true;
  b.set(h, typeof WeakRef === 'function' ? new WeakRef(n) : { deref: () => n });
  borrowedRegistry?.register(n, { hs, h });
  return n;
}

// ---------------------------------------------------------------------------------------------
// Containers, regions and blocks

export function slot(node, name = null) {
  let s = node.slots.get(name);
  if (!s) node.slots.set(name, (s = new Slot(node, name)));
  return s;
}

export function append(container, node) {
  node.owner = container;
  container.items.push(node);
  attach(node);
}

export function region(container) {
  return newRegion(container);
}

/** Runs `fn(region, ...args)` in a new branch effect + ownership scope at the end of `parent`. */
function open(parent, owner, fn, b = newRegion(parent), ...args) {
  b.scope = new Scope(owner);
  const prev = scope;
  scope = b.scope;
  try {
    b.effect = branch(() => fn(b, ...args));
  } finally {
    scope = prev;
  }
  return b;
}

function close(b) {
  destroy(b.effect);
  dispose(b.scope, b);
  const list = b.owner.items;
  const i = list.indexOf(b);
  if (i >= 0) list.splice(i, 1);
}

/**
 * Ownership teardown: (1) remove the region's inserted natives from their native parent (only at
 * the top of a disposal: nested natives go with their parent), (2) dispose child scopes, (3)
 * destroy own natives, children before parents, (4) drop the scope's handlers.
 */
function dispose(s, region) {
  if (region) for (const n of natives(region)) detach(n);
  for (const c of s.children) dispose(c, null);
  const walk = (n) => {
    for (const sl of n.slots.values()) for (const c of allNatives(sl)) if (c.scope === s && !c.destroyed) walk(c);
    n.destroyed = true;
    n.np = null;
    if (n.sc) forgetStyle(n);
    if (!n.dead) {
      table(n.host).delete(n.h);
      n.host.destroy(n.h);
    }
  };
  for (const n of s.natives) if (!n.destroyed) walk(n);
  for (const [node, signal, fn, flags] of s.handlers) off(node, signal, fn, flags);
  s.parent?.children.delete(s);
}

function allNatives(item, out = []) {
  if (item instanceof Native) out.push(item);
  else for (const x of item.items) allNatives(x, out);
  return out;
}

// ---- TR1: outros (Svelte's pause_effect / resume_effect on our branches) ----

/** Removes a closed or finished branch region from its container's list. */
function unlist(b) {
  const list = b.owner.items;
  const i = list.indexOf(b);
  if (i >= 0) list.splice(i, 1);
}

/**
 * Takes a branch away: its out transitions play first (Svelte's `pause_effect`: the subtree is
 * inert, its natives stay in place and are skipped as insertion anchors), then the effect is
 * destroyed, the natives removed and destroyed, and `done` called. Without transitions this is
 * synchronous and the same as `close`. An ancestor destroyed meanwhile aborts the outro: the
 * natives then go with the ancestor's scope and `done` never runs.
 */
function leave(b, done) {
  if (!b.effect || effectDestroyed(b.effect)) {
    close(b);
    done?.();
    return;
  }
  b.outro = true;
  pause(b.effect, () => {
    b.outro = false;
    dispose(b.scope, b);
    unlist(b);
    done?.();
  });
}

/** Brings back an outroing branch (its intros reverse the outros from where they are). */
function back(b) {
  b.outro = false;
  resume(b.effect);
}

const sameKey = (a, b) => a === b || (a !== a && b !== b);

/**
 * Svelte's `BranchManager` for one region: at most one branch per key on screen, plus the ones
 * still outroing. `ensure(key, fn)` shows the branch for `key` (resuming it if it is outroing,
 * else building it after the others) and lets every other branch leave. Keys compare with
 * SameValueZero (a Map).
 */
class Branches {
  constructor(r, owner) {
    this.r = r;
    this.owner = owner;
    this.on = new Map();
  }

  ensure(key, fn, ...args) {
    let cur = this.on.get(key);
    if (cur) {
      if (cur.outro) back(cur);
    } else if (fn) {
      // the new branch goes after the old ones, which leave afterwards (same op order as
      // Svelte's own blocks: build, insert, then remove + destroy the old branch)
      cur = open(this.r, this.owner, fn, newRegion(this.r), ...args);
      this.on.set(key, cur);
    }
    for (const [k, b] of this.on) {
      if (sameKey(k, key) || b.outro) continue;
      leave(b, () => {
        if (this.on.get(k) === b) this.on.delete(k);
      });
    }
  }
}

/**
 * `{#if}`. `elseif`: an `{:else if}` block, transparent for local transitions (Svelte's
 * `EFFECT_TRANSPARENT`), so `{#if a}..{:else if b}<x transition:fade/>` plays when `a`/`b` change.
 */
export function if_block(container, test, consequent, alternate = null, elseif = false) {
  const branches = new Branches(newRegion(container), scope);
  let shown;
  block(
    () => {
      const v = !!test();
      if (v === shown) return;
      shown = v;
      branches.ensure(v, v ? consequent : alternate);
    },
    elseif ? EFFECT_TRANSPARENT : 0,
  );
}

/** `each_block` flag: the collection reads a store, so its items are mutable sources (a store
 * mutation re-sets the same objects, which must still update the rows; Svelte's
 * `EACH_ITEM_IMMUTABLE` is unset then). */
export const EACH_ITEM_MUTABLE = 1;

export function each_block(container, collection, key, render, fallback = null, flags = 0) {
  const r = newRegion(container);
  const owner = scope;
  let items = [];
  // TR1: removed items still outroing, by key (keyed) or index: a key that comes back resumes its item
  const gone = new Map();
  let fb = null;
  block(() => {
    const c = collection();
    const arr = Array.isArray(c) ? [...c] : Array.from(c ?? []);
    const self = active();
    $.untrack(() => {
      if (arr.length && fb && !fb.outro) {
        const f = fb;
        leave(f, () => {
          if (fb === f) fb = null;
        });
      }
      const mutable = (flags & EACH_ITEM_MUTABLE) !== 0;
      const item = { render, mutable, collection };
      items = key ? keyed(r, owner, items, arr, key, item, gone) : indexed(r, owner, items, arr, item, gone);
      if (key) reorder(self, r.items.map((b) => b.effect).filter(Boolean));
      if (!arr.length && fallback) {
        if (fb?.outro) back(fb);
        else if (!fb) fb = open(r, owner, fallback);
      }
    });
  });
}

/**
 * TR1: removed each items leave together (Svelte's `pause_effects`): each is paused (its outros
 * play) and all of them are destroyed once the last outro of the group ended. `gone` maps their
 * keys to them meanwhile; a key that comes back is resumed (`revive`) and leaves the group.
 */
function leaveGroup(removed, gone) {
  if (!removed.length) return;
  const group = { pending: new Set(), done: [] };
  for (const b of removed) {
    b.outro = true;
    b.group = group;
    gone.set(b.key, b);
    group.pending.add(b);
  }
  for (const b of removed) {
    if (!b.effect || effectDestroyed(b.effect)) {
      group.pending.delete(b);
      group.done.push(b);
      continue;
    }
    pause(
      b.effect,
      () => {
        if (!group.pending.delete(b)) return;
        group.done.push(b);
        if (group.pending.size === 0) finishGroup(group, gone);
      },
      false,
    );
  }
  if (group.pending.size === 0) finishGroup(group, gone);
}

/** Destroys the items of a leave group whose outros all ended. */
function finishGroup(group, gone) {
  const done = group.done;
  group.done = [];
  for (const d of done) {
    if (gone.get(d.key) === d) gone.delete(d.key);
    d.outro = false;
    d.group = null;
    close(d);
  }
}

/** TR1: an outroing each item whose key is back: resumed, out of its leave group. */
function revive(b, gone) {
  gone.delete(b.key);
  const g = b.group;
  b.group = null;
  if (g) {
    g.pending.delete(b);
    if (g.pending.size === 0 && g.done.length) finishGroup(g, gone);
  }
  back(b);
}

/** Outroing regions and the fallback: kept after the live items (they are never anchors). */
const floating = (r, live) => r.items.filter((x) => !live.has(x));

/**
 * `{#key expr}`: a branch rebuilt (new natives, then the old ones removed + destroyed) whenever
 * `getKey()` changes. Keys compare like Svelte's (SameValueZero: NaN equals NaN, objects by
 * identity).
 */
export function key_block(container, getKey, render) {
  const branches = new Branches(newRegion(container), scope);
  let has = false;
  let key;
  block(() => {
    const k = getKey();
    if (has && sameKey(k, key)) return;
    has = true;
    key = k;
    branches.ensure(k, render);
  });
}

/**
 * `{@render f(...)}` where `f` can change (a snippet prop): `getSnippet()` is tracked; a different
 * function replaces the branch, a nullish one renders nothing. `args` are thunks.
 */
export function snippet(container, getSnippet, ...args) {
  // Svelte's snippet block: a nullish snippet is an error in DEV (`{@render f?.()}` compiles to
  // `?? $.noop` instead), nothing in production
  const get = DEV
    ? () => {
        const s = getSnippet();
        if (s == null) svelteError('invalid_snippet', 'Could not `{@render}` snippet due to the expression being `null` or `undefined`. Consider using optional chaining `{@render snippet?.()}`');
        return s;
      }
    : getSnippet;
  swapping(container, get, (s, anchor) => s(anchor, ...args));
}

/**
 * Dev (`--dev`): the first statement of every snippet (Svelte's `validate_snippet_args`): a
 * snippet is only called by `{@render}`, with a container (Svelte: a DOM `Node`) and thunks.
 */
export function validate_snippet_args(anchor, ...args) {
  const container = anchor instanceof Slot || anchor instanceof Region || anchor instanceof Root;
  if (!container || args.some((a) => typeof a !== 'function')) {
    svelteError('invalid_snippet_arguments', 'A snippet function was passed invalid arguments. Snippets should only be instantiated via `{@render ...}`');
  }
}

/**
 * Dev (`--dev`): an event handler that is not an inline function (Svelte's `$.apply`): calls the
 * value `thunk()` returns, warning `event_handler_invalid` when it is not a function. `event` and
 * `loc` (`file:line:column`) are static (Svelte reads the DOM event's type and phase).
 */
export function apply(thunk, node, args, event, loc, has_side_effects = false, remove_parens = false) {
  let handler;
  let error;
  try {
    handler = thunk();
  } catch (e) {
    error = e;
  }
  if (typeof handler !== 'function' && (has_side_effects || handler != null || error)) {
    svelteWarn('event_handler_invalid', `\`${event}\` handler at ${loc} should be a function. Did you mean to ${remove_parens ? 'remove the trailing `()`' : 'add a leading `() =>`'}?`);
    if (error) throw error;
  }
  handler?.apply(node, args);
}

/** Warns as svelte/src/internal/client/warnings.js does. */
function svelteWarn(code, message) {
  if (DEV) console.warn(`%c[svelte] ${code}\n%c${message}\nhttps://svelte.dev/e/${code}`, 'font-weight: bold', 'font-weight: normal');
  else console.warn(`https://svelte.dev/e/${code}`);
}

/** Throws a Svelte runtime error as svelte/src/internal/{client,shared}/errors.js does. */
function svelteError(code, message) {
  if (!DEV) throw new Error(`https://svelte.dev/e/${code}`);
  const error = new Error(`${code}\n${message}\nhttps://svelte.dev/e/${code}`);
  error.name = 'Svelte error';
  throw error;
}

/**
 * A dynamic component with `bind:this`: like `snippet(container, getComponent, props)`, and
 * `bind(exports)` runs inside each instance's branch (`$.bind_this`), so the binding is cleared
 * when the component goes and set again for the next one.
 */
export function component(container, getComponent, props, bind) {
  swapping(container, getComponent, (c, anchor) => bind(c(anchor, props)));
}

function swapping(container, get, render) {
  const branches = new Branches(newRegion(container), scope);
  let fn;
  let first = true;
  // transparent (Svelte's snippet and svelte:component blocks): a local transition inside plays
  // when the enclosing block changes
  block(() => {
    const s = get() ?? null;
    if (!first && s === fn) return;
    first = false;
    fn = s;
    branches.ensure(s, s && ((anchor) => render(s, anchor)));
  }, EFFECT_TRANSPARENT);
}

/**
 * `<svelte:boundary>` (Svelte's dom/blocks/boundary.js, synchronous part): renders
 * `props.children`; an error while creating it, or later in its effects, removes the content,
 * then in a microtask calls `props.onerror(error, reset)` and renders
 * `props.failed(anchor, () => error, () => reset)`. `reset()` renders the children again (once
 * per error). Without `onerror` and `failed` the error goes to the enclosing boundary. Called
 * like a component: `$n.boundary($n.region(container), props)`. `pending` is ignored (no async
 * mode).
 */
export function boundary(container, props) {
  const r = newRegion(container);
  const owner = scope;
  const parent = current_boundary();
  const view = $.state(0); // bumped to re-render (children again after reset, or `failed`)
  let views = 0;
  let failure = null; // { error, reset } while `failed` is shown
  let current = null;
  let effect = null;
  const destroyed = () => effectDestroyed(effect);

  const b = boundary_handler({
    parent,
    error(error) {
      if (!props.onerror && !props.failed) throw error;
      if (current) {
        close(current);
        current = null;
      }
      // the core's task queue: flushSync() drains it, as for Svelte's own boundary
      queue_task(() => {
        if (destroyed()) return;
        handle(b.transform_error(error));
      });
    },
  });

  // Svelte's invoke_error_boundary from this boundary's parent: the first enclosing boundary
  // that handles it (one without `onerror`/`failed` rethrows)
  const rethrow = (e) => {
    for (let p = parent; p; p = p.parent) {
      try {
        p.error(e);
        return;
      } catch (x) {
        e = x;
      }
    }
    throw e;
  };

  function handle(error) {
    let did_reset = false;
    let calling_onerror = false;
    const reset = () => {
      if (destroyed()) return;
      if (did_reset) {
        // Svelte's w.svelte_boundary_reset_noop (development format)
        console.warn(
          '%c[svelte] svelte_boundary_reset_noop\n%cA `<svelte:boundary>` `reset` function only resets the boundary the first time it is called\nhttps://svelte.dev/e/svelte_boundary_reset_noop',
          'font-weight: bold',
          'font-weight: normal',
        );
        return;
      }
      did_reset = true;
      if (calling_onerror) throw new Error('svelte_boundary_reset_onerror\nA `<svelte:boundary>` `reset` function cannot be called while an error is still being handled');
      failure = null;
      $.set(view, ++views);
    };
    try {
      calling_onerror = true;
      props.onerror?.(error, reset);
      calling_onerror = false;
    } catch (e) {
      rethrow(e);
    }
    if (props.failed && !destroyed() && !did_reset) {
      failure = { error, reset };
      $.set(view, ++views);
    }
  }

  // a branch that handles errors of its effects through `b` (errors during its creation throw)
  function render(fn) {
    const region = newRegion(r);
    try {
      return open(r, owner, (anchor) => {
        boundary_scope(b);
        fn(anchor);
      }, region);
    } catch (e) {
      dispose(region.scope, region);
      const i = r.items.indexOf(region);
      if (i >= 0) r.items.splice(i, 1);
      throw e;
    }
  }

  block(() => {
    effect = active();
    $.get(view);
    $.untrack(() => {
      if (current) {
        close(current);
        current = null;
      }
      const f = failure;
      if (f) {
        // an error while creating `failed` goes to the enclosing boundary (later errors in its
        // effects come back to this one, as in Svelte)
        try {
          current = render((anchor) => props.failed(anchor, () => f.error, () => f.reset));
        } catch (e) {
          rethrow(e);
        }
      } else {
        try {
          current = render((anchor) => props.children?.(anchor));
        } catch (e) {
          b.error(e);
        }
      }
    });
    // transparent for local transitions, as Svelte's boundary block
  }, EFFECT_TRANSPARENT);
}

const PENDING = 0;
const THEN = 1;
const CATCH = 2;

const is_promise = (v) => v != null && typeof v.then === 'function';

/**
 * `{#await}` with Svelte 5's resolution order (svelte/src/internal/client/dom/blocks/await.js):
 * a non-promise shows `then` immediately; a promise shows nothing synchronously, `pending` from
 * Svelte's microtask queue unless it has settled by then (an already-resolved promise never shows
 * `pending`; a `flushSync` before the microtask runs the queue, so `pending` shows at once), then
 * `then`/`catch` when it settles, unless a newer input (or teardown) superseded it. Settling into
 * the branch already shown only updates its value source. A rejection without `catch` is rethrown
 * (an unhandled rejection, as in Svelte). As in Svelte, the callbacks build their branch directly,
 * under the block effect (`capture_context`), and then flush: a branch shown by the `pending` task
 * renders even when the same flush tears the block down (`{#if p}{#await p}` with `p` cleared).
 */
export function await_block(container, getInput, pending, then, catch_) {
  const branches = new Branches(newRegion(container), scope);
  const value = $.state(undefined);
  const error = $.state(undefined);
  let shown = -1;
  const show = (s) => {
    if (s === shown) return;
    shown = s;
    const fn = s === PENDING ? pending : s === THEN ? then : catch_;
    branches.ensure(s, fn, s === THEN ? value : error);
  };
  block(() => {
    const input = getInput();
    let destroyed = false;
    if (is_promise(input)) {
      const restore = capture_context();
      let resolved = false;
      const resolve = (fn) => {
        if (destroyed) return;
        resolved = true;
        restore(false);
        try {
          fn();
        } finally {
          release_context();
          if (!flushing_sync()) flush();
        }
      };
      input.then(
        (v) =>
          resolve(() => {
            $.untrack(() => $.set(value, v));
            show(THEN);
          }),
        (e) =>
          resolve(() => {
            $.untrack(() => $.set(error, e));
            show(CATCH);
            if (!catch_) throw e;
          }),
      );
      queue_task(() => {
        if (!resolved) resolve(() => show(PENDING));
      });
    } else {
      $.untrack(() => $.set(value, input));
      show(THEN);
    }
    return () => {
      destroyed = true;
    };
  });
}

/** The class set of a dynamic `class` value (Svelte's clsx: strings, arrays, objects). */
export function classes(value) {
  return new Set(clsx(value).split(/\s+/).filter(Boolean));
}

/** `item`: the each block's `render`, `mutable` (EACH_ITEM_MUTABLE) and `collection`. */
function openItem(r, owner, item, b, value, index) {
  b.item = item.mutable ? mutable_state(value) : $.state(value);
  b.index = $.state(index);
  trace_item(b.item, () => item.collection()[$.untrack(() => $.get(b.index))]);
  return open(r, owner, (anchor) => item.render(anchor, b.item, b.index), b);
}

function indexed(r, owner, old, arr, item, gone) {
  const n = Math.min(old.length, arr.length);
  for (let i = 0; i < n; i++) $.set(old[i].item, arr[i]);
  const removed = [];
  for (let i = old.length - 1; i >= arr.length; i--) {
    old[i].key = i;
    removed.push(old[i]);
  }
  leaveGroup(removed, gone);
  const out = old.slice(0, n);
  for (let i = n; i < arr.length; i++) {
    const b = gone.get(i);
    if (b) {
      // TR1: an item still outroing at this index comes back with the new value
      revive(b, gone);
      $.set(b.item, arr[i]);
      out.push(b);
    } else out.push(openItem(r, owner, item, newRegion(r), arr[i], i));
  }
  // live items in order, then whatever is still outroing
  r.items = [...out, ...floating(r, new Set(out))];
  return out;
}

function keyed(r, owner, old, arr, key, item, gone) {
  const keys = arr.map((v, i) => {
    const k = key(v, i);
    if (DEV) {
      // Svelte's each block: the key function must be idempotent
      const again = key(v, i);
      if (k !== again) svelteError('each_key_volatile', `Keyed each block has key that is not idempotent — the key for item at index ${i} was \`${String(k)}\` but is now \`${String(again)}\`. Keys must be the same each time for a given item`);
    }
    return k;
  });
  if (new Set(keys).size !== keys.length) throw new Error('each_block: duplicate keys');
  const byKey = new Map(old.map((b) => [b.key, b]));
  const oldIndex = new Map(old.map((b, i) => [b, i]));
  const wanted = new Set(keys);
  // TR1 animate: (FLIP): where the items that stay are now (Svelte's each: measure before reconcile)
  const toAnimate = [];
  for (const b of old) {
    if (wanted.has(b.key) && b.effect?.nodes?.a) {
      b.effect.nodes.a.measure();
      toAnimate.push(b);
    }
  }
  leaveGroup(
    old.filter((b) => !wanted.has(b.key)),
    gone,
  );
  // outroing items whose key is back are resumed and moved into place like kept ones
  for (const k of keys) {
    const b = !byKey.has(k) && gone.get(k);
    if (b) {
      revive(b, gone);
      byKey.set(k, b);
    }
  }

  const next = keys.map((k, i) => {
    const b = byKey.get(k);
    if (b) {
      $.set(b.item, arr[i]);
      $.set(b.index, i);
      return b;
    }
    const nb = new Region(r);
    nb.key = k;
    return nb;
  });
  const stay = lis(next.map((b) => (b.effect && oldIndex.has(b) ? oldIndex.get(b) : -1)));
  r.items = [...next, ...floating(r, new Set(next))];
  // Moves back to front, so everything after position i is already in its final place (new items
  // have no natives yet and are skipped by nextNative). Then new items front to back: creation
  // order decides handle numbers, which must follow source order.
  for (let i = next.length - 1; i >= 0; i--) if (next[i].effect && !stay.has(i)) move(next[i]);
  for (let i = 0; i < next.length; i++) if (!next[i].effect) openItem(r, owner, item, next[i], arr[i], i);
  // TR1 animate: the items that stayed play their animation from the measured rect, in Svelte's
  // task queue after the update (the host's layout must be current by then: TR1 section 4)
  if (toAnimate.length) {
    queue_task(() => {
      for (const b of toAnimate) if (b.effect && !effectDestroyed(b.effect) && !b.outro) b.effect.nodes?.a?.apply();
    });
  }
  return next;
}

function move(b) {
  const before = nextNative(b);
  for (const n of natives(b)) {
    if (unplaced(n)) continue;
    n.host.remove(n.np.h, n.h);
    n.host.insert(n.np.h, n.h, before ? before.h : null, n.slotName ?? undefined);
    applyChildAttrs(n);
  }
}

/** Indices of a longest strictly increasing subsequence of `a`, ignoring entries < 0. */
export function lis(a) {
  const tails = []; // index into a of the smallest tail of each length
  const prev = new Array(a.length).fill(-1);
  for (let i = 0; i < a.length; i++) {
    if (a[i] < 0) continue;
    let lo = 0;
    let hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (a[tails[mid]] < a[i]) lo = mid + 1;
      else hi = mid;
    }
    if (lo > 0) prev[i] = tails[lo - 1];
    tails[lo] = i;
  }
  const out = new Set();
  for (let i = tails.length ? tails[tails.length - 1] : -1; i >= 0; i = prev[i]) out.add(i);
  return out;
}

// ---------------------------------------------------------------------------------------------
// TR1: transition:, in:, out:, animate:

/** Svelte's `effect.nodes` on a branch of ours (`end: null`: Svelte never removes DOM for it). */
function ensureNodes(e) {
  if (e && !e.nodes) e.nodes = { start: null, end: null, a: null, t: null };
  return e;
}

/**
 * `transition:fn={params}` / `in:` / `out:` (flags: Svelte's TRANSITION_IN 1, TRANSITION_OUT 2,
 * TRANSITION_GLOBAL 4). Svelte's own `$.transition` on the runtime node: it registers the manager
 * on the running branch, which `pause_effect` / `resume_effect` play when our blocks take the
 * branch away or bring it back.
 */
export function transition(flags, node, getFn, getParams) {
  ensureNodes(active());
  svelteTransition(flags, node, getFn, getParams ?? null);
}

/** `animate:fn={params}` on the only element of a keyed each item (FLIP: `measure` / `apply` in `keyed`). */
export function animation(node, getFn, getParams) {
  ensureNodes(active());
  svelteAnimation(node, getFn, getParams ?? null);
}

export { NativeAnimation, computed } from './motion.js';

// ---------------------------------------------------------------------------------------------
// Mount

/**
 * `target` (optional): an existing host handle to mount into (its default slot) instead of the
 * root container, like Svelte's `mount(App, { target })`. The target is not owned: unmount
 * removes the component's natives from it but never destroys it. Used by the DOM conformance
 * host (experiments/native-compiler/conformance).
 */
export function mount(Component, { props = {}, target, transformError, intro = true } = {}) {
  if (!host()) throw new Error('globalThis.__svelters_host is not defined');
  if (DEV) init_dev();
  globalThis.__svelters_dispatch = dispatch;
  globalThis.__svelters_dispatch_sync = dispatch_sync;
  globalThis.__svelters_gone = gone;
  globalThis.__svelters_node = nodeFor;
  // a runtime node (a list row's outlet, lists.js) or a bare host handle
  const mountNode = target == null ? null : target instanceof Native ? target : new Native('#target', target, null);
  if (mountNode) mountNode.mountTarget = true;
  const root = mountNode ? slot(mountNode, null) : new Root();
  const s = new Scope(null);
  const prev = scope;
  scope = s;
  let dispose_root;
  let exports;
  try {
    // In a branch, as Svelte's mount does (through its boundary): user effects created during the
    // root component's init are then deferred to its $.pop(), i.e. run after its children's.
    dispose_root = componentRoot(() => {
      // TR1: the root branch sits in a transparent block, as Svelte's mount renders the app in its
      // (transparent) boundary block: a local intro at the top level of the root component plays
      // when `intro` is set
      block(() => branch(() => {
        // the root of the boundary chain (Svelte's mount renders the app in a boundary): carries
        // `transformError` for every <svelte:boundary>, handles nothing itself
        root_boundary(
          boundary_handler({
            transform_error: transformError ?? ((e) => e),
            error(e) {
              throw e;
            },
          }),
        );
        // Svelte's `should_intro` while the root component initialises (mount's `intro` option)
        set_intro(intro);
        try {
          exports = Component(root, props);
        } finally {
          set_intro(true);
        }
      }), EFFECT_TRANSPARENT);
    });
  } catch (e) {
    // a failed first render: tear down what it already created (natives inserted under the
    // root or target, handlers, effects) before the error leaves mount
    scope = prev;
    try {
      dispose_root?.();
    } finally {
      dispose(s, root);
    }
    throw e;
  } finally {
    scope = prev;
  }
  function unmount() {
    dispose_root();
    dispose(s, root);
  }
  // what Svelte's mount returns: the component's exports (`export function ...`)
  unmount.exports = exports ?? {};
  return unmount;
}
